-- IPA 2021-07-25 Q63–80: reviewed adaptations and verified repeats.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2021-20210725-q63','exam-fe','SOA','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問63・改編】SOAを説明したものはどれか。','[{"id":"a","text":"業務・データ・適用処理・技術の4体系で業務とシステムの最適化を図る"},{"id":"b","text":"サービスというコンポーネントからソフトウェアを構築しビジネスの変化に対応しやすくする"},{"id":"c","text":"データフロー図を使い情報モデルと機能モデルを同時に作る"},{"id":"d","text":"連接、選択、反復の3構造でコンポーネントレベルの設計を行う"}]','"b"','SOAはサービスを組み合わせて業務機能を構成し、変更に柔軟に対応する考え方。中文：面向服务架构将服务组合为业务功能，提高变化时的灵活性。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q67','exam-fe','事業ポートフォリオ','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問67・改編】事業の魅力度（市場成長率）と事業の強み（市場シェア）の2軸のマトリックスで、事業計画や競争優位性を分析する目的はどれか。','[{"id":"a","text":"販促効果の測定のため事業の位置を評価する"},{"id":"b","text":"目標と資源配分の優先順位を決める基礎として事業の位置を評価する"},{"id":"c","text":"製品の品質を高める方策を評価する"},{"id":"d","text":"季節変動と地域差を加味して市場の変化を評価する"}]','"b"','市場成長率とシェアで事業を整理し、投資や資源配分の優先順位の判断に役立てる。中文：按市场增长率和份额分析各业务，支持投资和资源分配。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q68','exam-fe','製品ライフサイクル導入期','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問68・改編】製品ライフサイクルの導入期の説明はどれか。','[{"id":"a","text":"売上が急増し新規参入で競争が激化する"},{"id":"b","text":"売上と利益が減り市場撤退を検討する"},{"id":"c","text":"需要の伸びが鈍り品質改良でシェアを維持する"},{"id":"d","text":"先進的な消費者に販売し、製品の認知度を高める戦略をとる"}]','"d"','導入期には認知を高め、初期の顧客に製品を届ける。中文：导入期面向早期消费者推广，提高产品知名度。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q69','exam-fe','コストプラス価格','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問69・改編】コストプラス価格決定法の説明はどれか。','[{"id":"a","text":"買い手が認める品質と価格を調査して決める"},{"id":"b","text":"業界や競合の価格を参考に決める"},{"id":"c","text":"製造原価又は仕入原価に一定のマージンを乗せる"},{"id":"d","text":"目標販売量を基に総費用回収後に一定の利益率を確保する"}]','"c"','原価に一定の上乗せを加えて価格を定める。中文：成本加成定价法是在制造或采购成本上加一定利润。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q70','exam-fe','IoTの構成要素','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問70・改編】IoTの構成要素について適切な記述はどれか。','[{"id":"a","text":"アナログ機器を除くディジタル機器だけが対象"},{"id":"b","text":"インターネット又は閉域網に接続できる全てのものが対象"},{"id":"c","text":"自律的にデータ収集と分析をする機器だけが対象"},{"id":"d","text":"人や生物を除く形のあるものだけが対象"}]','"b"','IoTはネットワークに接続し情報をやり取りする多様な対象を扱う。中文：物联网可连接多种对象，不限于自主分析设备，也不限于排除人或生物。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q71','exam-fe','MRP','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問71・改編】MRPの特徴はどれか。','[{"id":"a","text":"顧客の注文後に製品を生産する"},{"id":"b","text":"作業指示票で作業と運搬を指示する"},{"id":"c","text":"開発、設計、生産準備を同時並行する"},{"id":"d","text":"基準生産計画と手持在庫を基に部品の手配数量を算出する"}]','"d"','MRPは生産計画、部品構成、在庫などから必要な資材の数量と時期を計画する。中文：物料需求计划依据生产计划、物料清单与库存计算采购或生产需求。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q73','exam-fe','O to O','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問73・改編】マーケティング施策のO to Oの説明はどれか。','[{"id":"a","text":"基本機能を無料、特別機能を有料で提供する"},{"id":"b","text":"注文後に顧客仕様に応じて最終製品の生産を始める"},{"id":"c","text":"代金と商品の受渡しトラブルを防ぐ"},{"id":"d","text":"顧客をオンライン店舗と実店舗の間で誘導し購入につなげる"}]','"d"','Online to Offline等はオンラインと実店舗の顧客接点を結び購買を促す。中文：O2O连接线上与线下的顾客接触点，引导购买。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q75','exam-fe','マトリックス組織','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問75・改編】マトリックス組織の説明はどれか。','[{"id":"a","text":"製品別や地域別に必要な機能と利益責任を持つ"},{"id":"b","text":"構成員が専門の機能部門と特定事業を遂行する部門の両方に所属する"},{"id":"c","text":"購買、生産、販売など職能別の部門を持つ"},{"id":"d","text":"特定課題のため各部門から専門家を集めた期間限定の組織"}]','"b"','機能別と事業・プロジェクト別など複数の軸を組み合わせる組織。中文：矩阵组织使成员同时隶属职能部门和项目或业务部门。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q76','exam-fe','散布図の負の相関','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問76・改編】次の散布図の特徴を文字で表した。負の相関を示すものはどれか。','[{"id":"a","text":"xが0付近でyが高く、左右に離れると低くなる山形"},{"id":"b","text":"xが増えるにつれてyが低くなる傾向の点群"},{"id":"c","text":"xの増加に対してyに明確な傾向がない点群"},{"id":"d","text":"xが増えるにつれてyが高くなる傾向の点群"}]','"b"','負の相関は一方が大きくなると他方が小さくなる傾向。中文：负相关指一个变量增加时另一个变量倾向于下降。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q77','exam-fe','定量発注の在庫調整','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問77・改編】定量発注方式で、当初の予定では納品直前に安全在庫Sとなり、発注量Eが届くと最大在庫に達する。発注後に予測使用量が変わり、納品直前の予測在庫がSより大きいXになった。発注量は変更可能で、納品直後に最大在庫を超えてはならない。適切な変更はどれか。','[{"id":"a","text":"E+S−Xを追加発注する"},{"id":"b","text":"K+S−Xを追加発注する"},{"id":"c","text":"K−Xだけ発注を取り消す"},{"id":"d","text":"X−Sだけ発注を取り消す"}]','"d"','最大在庫はS+E。予測在庫がXに増えた分X−Sだけ発注量を減らせばX+(E−(X−S))=S+E。中文：预计库存比安全库存多X−S，为不超过上限，将原订单减少同样数量。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q78','exam-fe','先入先出法','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問78・改編】在庫は1日繰越100個×200円、5日仕入50個×215円、15日売上70個、20日仕入100個×223円、25日売上60個、30日翌月繰越120個。先入先出法による当月売上原価は何円か。','[{"id":"a","text":"26290"},{"id":"b","text":"26450"},{"id":"c","text":"27250"},{"id":"d","text":"27586"}]','"b"','15日の70個は200円、25日の60個は200円の残30個と215円の30個。合計100×200+30×215=26450円。中文：先售出期初100件，再售出5日购入的30件，成本26450日元。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q79','exam-fe','不正指令電磁的記録','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問79・改編】コンピュータウイルスを作成する行為を処罰の対象とする法律はどれか。','[{"id":"a","text":"刑法"},{"id":"b","text":"不正アクセス禁止法"},{"id":"c","text":"不正競争防止法"},{"id":"d","text":"プロバイダ責任制限法"}]','"a"','不正指令電磁的記録に関する罪は刑法に規定される。中文：日本刑法规定了与非法指令电磁记录相关的犯罪。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q80','exam-fe','請負契約と指揮命令','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問80・改編】発注者と受注者がソフトウェア開発の請負契約を結び、発注者の事業所で作業する。指揮命令権と雇用契約について適切なものはどれか。','[{"id":"a","text":"発注者に指揮命令権があり、作業者は発注者と新たに雇用契約を結ぶ"},{"id":"b","text":"発注者に指揮命令権があり、作業者は発注者と雇用契約を結ばない"},{"id":"c","text":"発注者に指揮命令権はないが、作業者は発注者と新たに雇用契約を結ぶ"},{"id":"d","text":"発注者に指揮命令権はなく、作業者は発注者と新たに雇用契約を結ばない"}]','"d"','請負では受注者が自社の労働者に指揮命令し、発注者との新たな雇用契約は不要。中文：承揽中承包方指挥自己的员工，员工无需与发包方另签劳动合同。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption');
